import{_ as t,o as a,c as n,ah as o}from"./chunks/framework.CRsDMGp2.js";const p=JSON.parse('{"title":"Guide — Administrator","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/administrateur.md","filePath":"src/en/guide/administrateur.md"}'),r={name:"en/guide/administrateur.md"};function i(s,e,l,c,d,u){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="guide-—-administrator" tabindex="-1">Guide — Administrator <a class="header-anchor" href="#guide-—-administrator" aria-label="Permalink to &quot;Guide — Administrator&quot;">​</a></h1><p>Administer accounts, billing and security.</p><p>As an Administrator, you have full access to the platform.</p><h2 id="account-and-access-management" tabindex="-1">Account and access management <a class="header-anchor" href="#account-and-access-management" aria-label="Permalink to &quot;Account and access management&quot;">​</a></h2><ul><li>Create and manage user accounts (internal, clients, partners, referrers) from <strong>Users</strong>, and assign them a role.</li><li>Also from <strong>Users</strong>, create the accounts of the Commercial, Support, HR and Billing poles&#39; <strong>external contributors</strong>, picking the matching pole&#39;s role. Only you create and revoke these accounts; to revoke access, suspend the account. A collaborator or external expert the HR pole must be able to assign to a project first needs their own account.</li><li>Manage organizations (clients, partners) from <strong>Organizations</strong>.</li><li>Configure <strong>project types</strong> from <strong>Project types</strong>: each type&#39;s default phases, milestones and billing percentages — these are the templates that automatically pre-fill a new project when a project manager creates it.</li></ul><h2 id="billing" tabindex="-1">Billing <a class="header-anchor" href="#billing" aria-label="Permalink to &quot;Billing&quot;">​</a></h2><ul><li>Generate and send the corresponding invoice (deposit, intermediate, balance, or equipment) when a billable milestone is validated by the project manager.</li><li>Generate the <strong>delivery note</strong> and the <strong>completion certificate</strong>, then send them out for electronic signature to the client.</li><li>Freely create quotes and pro forma invoices, even before a project exists, from <strong>Quotes</strong> and <strong>Pro forma invoices</strong>.</li><li>Configure and oversee online payment methods (Mobile Money, card) and track payments received from each project&#39;s billing page.</li></ul><h2 id="external-ecosystem" tabindex="-1">External ecosystem <a class="header-anchor" href="#external-ecosystem" aria-label="Permalink to &quot;External ecosystem&quot;">​</a></h2><ul><li>Set each referrer&#39;s commission rate from their user page (typically between 5 and 15%, adjustable case by case) and track the total of their commissions due and paid.</li><li>Approve invoices submitted by partners on each project&#39;s <strong>Partner payments</strong> tab, and record their payment once it&#39;s been made.</li><li>Generate the amendment document at the project manager&#39;s request and track its signature by the client.</li><li>From a partner&#39;s or referrer&#39;s page, download the blank contract templates (framework agreement, mission sheet, confidentiality agreement, agency agreement) to hand to them — this action is also available to the project manager from a project&#39;s team.</li></ul><h2 id="pole-submissions" tabindex="-1">Pole submissions <a class="header-anchor" href="#pole-submissions" aria-label="Permalink to &quot;Pole submissions&quot;">​</a></h2><p>The <strong>Pole submissions</strong> page gathers what external contributors send that needs your action:</p><ul><li><strong>Project requests</strong> (Commercial pole): pick the client — the matching existing client, or create it if it&#39;s new —, appoint the project manager, adjust the name if needed, then click <strong>Create the project</strong>. The project is created with its reference (<code>NAIA-0142</code>) and the project manager is notified.</li><li><strong>Development needs to triage</strong> (Support and Commercial poles): a need sent without a known project waits here until you pick the project concerned. <strong>Create the task</strong> adds it to the project, with a badge showing its origin.</li><li><strong>Discard</strong> removes an invalid submission; it disappears from its author&#39;s list, and the audit log keeps a trace of it.</li></ul><p>You&#39;re notified, in the app and by e-mail, of every new submission.</p><h2 id="blocking-for-non-payment-and-security" tabindex="-1">Blocking for non-payment and security <a class="header-anchor" href="#blocking-for-non-payment-and-security" aria-label="Permalink to &quot;Blocking for non-payment and security&quot;">​</a></h2><ul><li>When the Billing pole reports a payment as <strong>overdue</strong>, you&#39;re alerted, as is Direction. From the project page, choose <strong>Block the project</strong> or <strong>Do not block</strong>. Once the payment is back up to date, <strong>unblock the project</strong>.</li><li>Blocking is a &quot;soft&quot; lock: tasks already started can finish, but nobody — the project manager included — can start a new task or validate a milestone. Everything else remains possible, including paying. Only the project concerned is blocked, never the client&#39;s other projects.</li><li>Review the <strong>audit log</strong> to trace actions taken on the platform.</li><li>Manage your own account&#39;s security (password, two-factor authentication) from <strong>Settings &gt; Security</strong> — enabling 2FA is automatically suggested to you when you sign in.</li></ul><h2 id="first-level-support" tabindex="-1">First-level support <a class="header-anchor" href="#first-level-support" aria-label="Permalink to &quot;First-level support&quot;">​</a></h2><p>You handle first-level support for platform users.</p><p><strong>Channels:</strong> a project&#39;s built-in messaging is the priority channel (keeps the history in its context); a dedicated support email covers requests outside the context of a specific project (e.g. a login issue).</p><p><strong>Categorizing requests:</strong></p><table tabindex="0"><thead><tr><th>Category</th><th>Examples</th><th>Indicative first-response time</th></tr></thead><tbody><tr><td>Access / login</td><td>Forgotten password, wrongly suspended account, blocking 2FA</td><td>4 business hours</td></tr><tr><td>Billing / payment</td><td>Invoice not received, failed online payment, disputed amount</td><td>1 business day</td></tr><tr><td>Functional</td><td>Usage question, unexpected feature behavior</td><td>1 business day</td></tr><tr><td>Technical issue</td><td>Blocking error, inaccessible page</td><td>4 business hours, immediate escalation if blocking</td></tr></tbody></table><p><strong>Handling:</strong> acknowledge the request → categorize it and verify the person legitimately has access to the resource in question → handle it directly if it&#39;s within your remit (resetting access, correcting an invoice, unblocking a project) → otherwise, escalate to the development team for any technical issue → confirm resolution with the requester.</p>',21)])])}const g=t(r,[["render",i]]);export{p as __pageData,g as default};
